import * as T from './vendor/three.module.min.js';import{GRID}from'./lotus-layout.mjs';import{SITES,DOORS,BREAKABLE,point,terrainHeight,nearestFloor}from'./lotus-map.mjs';
const cache=new Map();const mat=(c,em=0)=>{const key=c+em;if(!cache.has(key))cache.set(key,new T.MeshStandardMaterial({color:c,roughness:.95,flatShading:true,emissive:c,emissiveIntensity:em}));return cache.get(key);};const cube=new T.BoxGeometry(1,1,1),oct=new T.IcosahedronGeometry(1,0),cyl=new T.CylinderGeometry(1,1,1,8),ringG=new T.RingGeometry(.93,1,48);
const put=(p,g,c,x,y,z,sx,sy=sx,sz=sx)=>{const m=new T.Mesh(g,typeof c==='string'?mat(c):c);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;p.add(m);return m;};const box=(p,x,y,z,w,h,d,c)=>put(p,cube,c,x,y,z,w,h,d),ball=(p,x,y,z,r,c,ry=r)=>put(p,oct,c,x,y,z,r,ry,r),column=(p,x,y,z,r,h,c)=>put(p,cyl,c,x,y,z,r,h,r);
function ring(p,x,y,z,r,c){const m=put(p,ringG,new T.MeshBasicMaterial({color:c,side:T.DoubleSide,transparent:true,opacity:.85}),x,y,z,r,r,r);m.rotation.x=-Math.PI/2;return m;}
export function buildLotusScene(parent){const out={gates:[],walls:[],orbs:[],sites:[]};box(parent,80,-3.5,80,350,4,350,'#615d58');const d=new T.Object3D(),color=new T.Color();
 const floor=new T.InstancedMesh(cube,new T.MeshStandardMaterial({color:'#eee8df',roughness:1}),9163);let count=0;
 const walls=[];for(let z=0;z<160;z++)for(let x=0;x<160;x++){if(GRID[z][x]==='1'){const elevation=terrainHeight(x+.5,z+.5);d.position.set(x+.5,(elevation-.32)/2,z+.5);d.scale.set(1,elevation+.32,1);d.updateMatrix();floor.setMatrixAt(count,d.matrix);floor.setColorAt(count++,color.set((x%8===0||z%8===0)?'#a59b8e':(Math.floor(x/4)+Math.floor(z/4))%7===0?'#bab1a4':'#cec5b7'));}else{let near=false;for(let dz=-2;dz<=2&&!near;dz++)for(let dx=-2;dx<=2;dx++)if(GRID[z+dz]?.[x+dx]==='1'){near=true;break;}if(near)walls.push([x,z]);}}
 floor.count=count;floor.receiveShadow=true;parent.add(floor);const stone=new T.InstancedMesh(cube,mat('#8d8983'),walls.length),caps=new T.InstancedMesh(cube,mat('#c8bfb1'),walls.length);walls.forEach(([x,z],i)=>{const h=2.2+terrainHeight(x+.5,z+.5);d.position.set(x+.5,h/2,z+.5);d.scale.set(1,h,1);d.updateMatrix();stone.setMatrixAt(i,d.matrix);d.position.y=h+.13;d.scale.y=.22;d.updateMatrix();caps.setMatrixAt(i,d.matrix);});stone.castShadow=true;stone.receiveShadow=true;caps.castShadow=true;caps.receiveShadow=true;parent.add(stone,caps);
 // Batched architectural ribs and mineral seams: original, no downloaded textures.
 const ribs=new T.InstancedMesh(cube,mat('#6b6660'),Math.ceil(walls.length/7));let ri=0;walls.forEach(([x,z],i)=>{if(i%7)return;const h=2.2+terrainHeight(x+.5,z+.5);d.position.set(x+.5,h*.5,z+.5);d.scale.set(1.035,h*.75,.15);d.updateMatrix();ribs.setMatrixAt(ri++,d.matrix);});ribs.count=ri;parent.add(ribs);
 // Sparse, deliberate root circuits and lotus reliefs replace the random forest.
 const conduits=new T.InstancedMesh(cube,mat('#869da0',.18),Math.ceil(walls.length/8));let ci=0;walls.forEach(([x,z],i)=>{if(i%8)return;d.position.set(x+.5,2.55+terrainHeight(x,z),z+.5);d.scale.set(.13,.1,.85);d.updateMatrix();conduits.setMatrixAt(ci++,d.matrix);});conduits.count=ci;parent.add(conduits);
 for(const site of SITES){const y=terrainHeight(site.x,site.z)+.05;ring(parent,site.x,y,site.z,site.r,'#f1d797');for(let i=0;i<8;i++){const a=i*Math.PI/4,tick=box(parent,site.x+Math.sin(a)*(site.r+.5),y+.01,site.z+Math.cos(a)*(site.r+.5),.18,.04,.65,'#d9a16b');tick.rotation.y=a;}for(const sign of [-1,1]){const beacon=nearestFloor({x:site.x+sign*(site.r+1.7),z:site.z});column(parent,beacon.x,y+.65,beacon.z,.28,1.3,'#314f55');ball(parent,beacon.x,y+1.35,beacon.z,.25,'#a9e5d0');}const canvas=document.createElement('canvas');canvas.width=canvas.height=128;const c=canvas.getContext('2d');c.clearRect(0,0,128,128);c.strokeStyle='#f7e9ac';c.lineWidth=4;c.strokeRect(8,8,112,112);c.fillStyle='#f5e4a5';c.font='700 88px system-ui';c.textAlign='center';c.fillText(site.name,64,96);const tex=new T.CanvasTexture(canvas);const m=new T.Mesh(new T.PlaneGeometry(5,5),new T.MeshBasicMaterial({map:tex,transparent:true,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.set(site.x,y+.04,site.z);parent.add(m);out.sites.push(m);}
 for(const g of DOORS){const group=new T.Group();group.position.set(g.x,terrainHeight(g.x,g.z),g.z);group.rotation.y=g.angle;column(parent,g.x,.2+terrainHeight(g.x,g.z),g.z,3.6,.4,'#a9a194');box(group,0,1.7,0,1.05,3.4,5.7,'#bcb1a2');for(let i=-2;i<=2;i++)box(group,.55,1.7,i*1.1,.1,1.3,.28,'#799b9d');parent.add(group);out.gates.push(group);}
 const wall=new T.Group();wall.position.set(BREAKABLE.x,terrainHeight(BREAKABLE.x,BREAKABLE.z),BREAKABLE.z);for(let i=-1;i<=1;i++)box(wall,0,1.2,i*1.2,1.15,2.4,1.1,'#b9b0a3');for(let i=0;i<5;i++){const a=i/5*Math.PI*2;const b=ball(wall,.6,1.3+Math.cos(a)*.45,Math.sin(a)*.45,.24,'#9bc1bd',.4);b.scale.x=.08;}parent.add(wall);out.walls.push(wall);
 for(const name of ['A Root','C Mound']){const p=nearestFloor(point(name)),g=new T.Group();g.position.set(p.x,terrainHeight(p.x,p.z),p.z);column(g,0,.18,0,1.1,.3,'#77746d');ring(g,0,.45,0,1.4,'#b7dbc1');ball(g,0,1.6,0,.55,'#b6e9d5');parent.add(g);out.orbs.push(g);}
 // Landmark flowers, stone lintels, and radianite storage embedded in the ruins.
 for(const [x,z]of [[84,151],[148,78],[11,52]]){const group=new T.Group();group.position.set(x,0,z);for(let i=0;i<9;i++){const a=i/9*Math.PI*2,b=ball(group,Math.sin(a)*3,2.7,Math.cos(a)*3,1.7,'#d4c1cd',.55);b.scale.z=3.6;b.rotation.y=a;}ball(group,0,2.7,0,1.5,'#d3c185',.5);column(group,0,.6,0,.6,3,'#71695c');parent.add(group);}
 for(const [x,z]of [[118,49],[93,60],[27,54],[57,91],[106,114]]){const h=terrainHeight(x,z);for(const sign of [-1,1]){column(parent,x+sign*3,h+2.3,z,.6,4.6,'#b2a79a');box(parent,x+sign*3,h+4.7,z,1.8,.5,1.8,'#d6cabb');}box(parent,x,h+5,z,8,.5,2,'#bfb3a3');}
 for(const [x,z]of walls.filter((_,i)=>i%113===0).slice(0,18)){const h=terrainHeight(x,z)+2.4;box(parent,x+.5,h,z+.5,.8,.9,.8,'#526776');box(parent,x+.5,h+.5,z+.5,.6,.1,.6,'#91d4b5');}
 // A Drop is the silent one-way drop, rather than the earlier fictional zipline.
 const drop=point('A Drop');for(let i=0;i<4;i++){const height=1.5-i*.3;box(parent,drop.x,(height-.32)/2,drop.z+i*.9,2,height+.32,1,'#b7ab9d');}
 return out;}
